<?php
require_once 'includes/db.php'; require_once 'includes/auth.php';
if(logged()){header('Location: index.php');exit;}
$error='';
if (!isset($_SESSION['login_attempts'])) $_SESSION['login_attempts']=0;
if (!isset($_SESSION['login_locked_until'])) $_SESSION['login_locked_until']=0;
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); if(time() < (int)$_SESSION['login_locked_until']){$error='Muitas tentativas. Aguarde alguns minutos e tente novamente.';} else { $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $senha=$_POST['senha']??'';
    if($email && $senha){$st=db()->prepare('SELECT * FROM usuarios WHERE email=? LIMIT 1');$st->execute([$email]);$u=$st->fetch();if($u && password_verify($senha,$u['senha'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['nome']=$u['nome'];$_SESSION['perfil']=$u['perfil'];$_SESSION['login_attempts']=0;$_SESSION['login_locked_until']=0;header('Location: index.php');exit;} }
    if(!$error){$_SESSION['login_attempts']++;if($_SESSION['login_attempts']>=5){$_SESSION['login_locked_until']=time()+300;$_SESSION['login_attempts']=0;}$error='E-mail ou senha inválidos.';} }
}
